      function categoryModal(category){dq.modal(category?'Edit category':'Add menu category',`<form id="cat-form"><label>Category name<input class="input" name="name" value="${dq.esc(category?.name||'')}" placeholder="Main courses" required></label><label>Preparation area<select name="preparation_area"><option value="kitchen" ${category?.preparation_area!=='bar'?'selected':''}>Kitchen / food</option><option value="bar" ${category?.preparation_area==='bar'?'selected':''}>Bar / drinks</option></select><small class="muted">Items in this category will appear on the selected preparation screen.</small></label><label><span><input type="checkbox" name="active" ${category?.active===false?'':'checked'}> Show this category to customers</span></label><button class="btn">${category?'Save category':'Add category'}</button></form>`);document.getElementById('cat-form').onsubmit=async e=>{e.preventDefault();try{const {name,preparation_area}=dq.formData(e.target),payload={name:name.trim(),preparation_area,active:e.target.active.checked};if(!category){payload.restaurant_id=rid;payload.sort_order=Math.max(0,...cats.map(c=>Number(c.sort_order)||0))+10}const {error}=category?await dq.db.from('menu_categories').update(payload).eq('id',category.id):await dq.db.from('menu_categories').insert(payload);if(error)throw error;dq.closeModal();dq.toast(category?'Category updated.':'Category added.');menu()}catch(error){dq.err(error)}}}
      function itemModal(item){dq.modal(item?'Edit menu item':'Add menu item',`<form id="item-form"><label>Item name<input class="input" name="name" value="${dq.esc(item?.name||'')}" required></label><label>Description<textarea name="description" rows="3">${dq.esc(item?.description||'')}</textarea></label><div class="field-row"><label>Price (USD)<input class="input" type="number" step="0.01" min="0" name="price" value="${item?.price??''}" required></label><label>Category<select name="category_id"><option value="">Uncategorized</option>${cats.map(c=>`<option value="${c.id}" ${c.id===item?.category_id?'selected':''}>${dq.esc(c.name)}</option>`).join('')}</select></label></div><label>Item picture<input class="input" type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif"><small class="muted">JPG, PNG, WebP or GIF. Maximum 5 MB.${item?.image_url?' Leave empty to keep the current picture.':''}</small></label>${item?.image_url?`<img class="menu-preview" src="${dq.esc(item.image_url)}" alt="Current picture">`:''}<label><span><input type="checkbox" name="available" ${item?.available===false?'':'checked'}> Available to customers</span></label><button class="btn">${item?'Save changes':'Add item'}</button></form>`);document.getElementById('item-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button'),x=dq.formData(e.target),file=e.target.image.files[0],categoryId=x.category_id||null,siblingItems=items.filter(i=>(i.category_id||null)===categoryId),payload={restaurant_id:rid,name:x.name.trim(),description:x.description.trim(),price:Number(x.price),category_id:categoryId,available:e.target.available.checked,image_url:item?.image_url||null};if(!item||item.category_id!==categoryId)payload.sort_order=Math.max(0,...siblingItems.map(i=>Number(i.sort_order)||0))+10;dq.setBusy(button,true,file?'Uploading picture…':'Saving…');try{if(file)payload.image_url=await uploadMenuImage(file);const {error}=item?await dq.db.from('menu_items').update(payload).eq('id',item.id):await dq.db.from('menu_items').insert(payload);if(error)throw error;dq.closeModal();menu();dq.toast(item?'Menu item updated.':'Menu item added.')}catch(error){dq.err(error)}finally{dq.setBusy(button,false)}}}
      async function moveCategory(id,direction){const reordered=[...cats],index=reordered.findIndex(c=>c.id===id),target=direction==='up'?index-1:index+1;if(index<0||target<0||target>=reordered.length)return;[reordered[index],reordered[target]]=[reordered[target],reordered[index]];try{for(let position=0;position<reordered.length;position++){const {error}=await dq.db.from('menu_categories').update({sort_order:(position+1)*10}).eq('id',reordered[position].id);if(error)throw error}menu()}catch(error){dq.err(error)}}
      async function moveItem(id,direction){const item=items.find(i=>i.id===id),siblings=sortedItems.filter(i=>(i.category_id||'')===(item.category_id||'')),index=siblings.findIndex(i=>i.id===id),target=direction==='up'?index-1:index+1;if(index<0||target<0||target>=siblings.length)return;[siblings[index],siblings[target]]=[siblings[target],siblings[index]];try{for(let position=0;position<siblings.length;position++){const {error}=await dq.db.from('menu_items').update({sort_order:(position+1)*10}).eq('id',siblings[position].id);if(error)throw error}menu()}catch(error){dq.err(error)}}
      async function uploadMenuImage(file){if(file.size>5242880)throw new Error('The picture must be smaller than 5 MB.');if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))throw new Error('Please choose a JPG, PNG, WebP or GIF picture.');const extension=(file.name.split('.').pop()||'jpg').replace(/[^a-z0-9]/gi,'').toLowerCase(),filePath=`${rid}/${crypto.randomUUID()}.${extension}`;const {error}=await dq.db.storage.from('menu-images').upload(filePath,file,{cacheControl:'3600',upsert:false,contentType:file.type});if(error)throw error;return dq.db.storage.from('menu-images').getPublicUrl(filePath).data.publicUrl}
