      document.getElementById('invite').onclick=()=>{dq.modal('Add a staff member',`<form id="invite-form"><label>Full name<input class="input" name="staff_name" required></label><label>Email<input class="input" type="email" name="staff_email" required></label><label>Phone number<input class="input" type="tel" name="staff_phone" required></label><label>Role<select name="staff_role"><option value="waiter">Waiter</option><option value="kitchen">Kitchen</option><option value="bar">Bar</option><option value="cashier">Cashier</option>${role==='owner'?'<option value="manager">Manager</option>':''}</select></label><p class="muted">TafuraFlow will create a private signup link for this staff member.</p><button class="btn">Add staff member</button></form>`);document.getElementById('invite-form').onsubmit=async e=>{e.preventDefault();const x=dq.formData(e.target);try{const {data,error}=await dq.db.rpc('invite_staff',{target_restaurant:rid,...x});if(error)throw error;await staff();showInvitation(data.invite_token,x.staff_name)}catch(x){dq.err(x)}}};
